file.content:
@use "../abstract" as *;

// 캔버스 전용 고정 레이어 (뷰포트에 고정, 낮은 z-index)
.canvas-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;

  .no-marquee {
    height: 100vh;
    &__viewport {
      height: 100%;
      @include flex-center();
    }
  }

  #canvas {
    display: block;
    width: 100%;
    height: 100%;
  }
}

// 스크롤 콘텐츠 레이어 (캔버스 위에서 스크롤)
.main-content {
  position: relative;
  z-index: 1;
}

.scene-shell {
  position: relative;
  height: var(--scene-shell-span);
}

@keyframes no-intro-title-glow {
  0% {
    background-position: 100% 50%;
  }
  100% {
    background-position: -100% 50%;
  }
}

@keyframes no-intro-countdown-orbit-pulse {
  0%,
  7%,
  100% {
    opacity: 0.02;
  }

  10%,
  14% {
    opacity: 1;
  }
}

// 메인 씬 스타일
#main {
  p {
    color: var(--clr-text-body);
    font-weight: 400;
  }
}

.no-main {
  &-intro {
    width: 100%;
    &-1 {
      width: 50% !important;
      margin-right: auto;

      @include mq(lg) {
        width: 70% !important;
      }

      @include mq(md) {
        width: 100% !important;
      }

      h2 {
        .line {
          background: linear-gradient(
            120deg,
            rgba(255, 255, 255, 0.4) 0%,
            rgba(255, 255, 255, 0.4) 38%,
            rgba(255, 255, 255, 1) 50%,
            rgba(255, 255, 255, 0.4) 62%,
            rgba(255, 255, 255, 0.4) 100%
          );
          background-size: 300% 100%;
          -webkit-background-clip: text;
          background-clip: text;
          -webkit-text-fill-color: transparent;
          animation: no-intro-title-glow 8s linear infinite;
        }
      }
    }
    > div {
      height: 100vh;
    }
    &__inner {
      height: calc(100% - var(--header-height));
      margin-top: var(--header-height);
    }
    &__body {
      height: 100%;
      position: relative;
      padding: var(--gutter-2xl) 0;
    }

    &__txt {
      height: 100%;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: var(--gutter-2xl);
      &--hook {
        margin-left: auto;
        width: 30% !important;

        @include mq(lg) {
          width: 46% !important;
        }

        @include mq(md) {
          width: 100% !important;
          margin-left: 0;
        }

        h3 {
          margin-bottom: fluid(8, 16);
        }
      }
      &--top {
        display: flex;
        flex-direction: column;
        gap: var(--gutter-md);
        align-items: flex-end;

        @include mq(md) {
          align-items: flex-start;
        }
      }
      &--bottom {
        position: relative;

        @include mq(md) {
          display: flex;
          flex-direction: column;
          align-items: flex-start;
          gap: var(--gutter-lg);
        }

        .masking-text__line,
        .line {
        }
      }
    }
    &__cta {
      position: absolute;
      left: 0;
      bottom: 0;
      min-width: fluid(144, 196);
      gap: fluid(8, 12);
      color: var(--clr-text-title);

      @include mq(md) {
        position: relative;
        left: auto;
        bottom: auto;
      }

      @include mq(sm) {
        width: 100%;
      }

      .no-corner-btn__text {
        display: inline-flex;
        align-items: center;
      }

      .no-loop-filter-rect {
        margin-right: fluid(2, 4);
      }
    }
    &__title {
      overflow: hidden;
      width: 100%;

      h2 {
        color: var(--clr-text-title);
      }

      .line {
        display: flex;
        flex-direction: column;
      }
      h2 {
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }
    }
  }
  &-intro-action {
    width: 100%;

    > div {
      height: 100vh;
    }

    &__inner {
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;

      @include mq(md) {
        min-height: auto;
        flex-direction: column;
        align-items: stretch;
        justify-content: flex-start;
        padding-top: calc(var(--header-height) + var(--gutter-2xl));
        padding-bottom: var(--gutter-2xl);
      }
    }

    &__countdown {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      pointer-events: none;
      opacity: 0;
      z-index: 2;
      margin: auto;
    }

    &__countdown-shell {
      width: fluid(128, 180);
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      background: linear-gradient(
        180deg,
        rgba(255, 255, 255, 0.06) 0%,
        rgba(255, 255, 255, 0.02) 100%
      );
      backdrop-filter: blur(12px);
      overflow: hidden;
    }

    &__countdown-orbit {
      position: absolute;
      inset: 0;

      span {
        --countdown-y: 0;
        --countdown-x: 0;
        --countdown-delay: 0s;
        position: absolute;
        top: calc(var(--countdown-y) * 100%);
        left: calc(var(--countdown-x) * 100%);
        width: calc(100% / 25 + 1px);
        height: fluid(8, 14);
        background: #fff;
        animation: no-intro-countdown-orbit-pulse 1.92s linear infinite;
        animation-delay: var(--countdown-delay);
      }

      span[data-side="0"] {
        transform: translate(0, -50%);
      }

      span[data-side="1"],
      span[data-side="3"] {
        width: fluid(8, 14);
        height: calc(100% / 25 + 1px);
      }

      span[data-side="1"] {
        transform: translate(-50%, 0);
      }

      span[data-side="2"] {
        transform: translate(-100%, -50%);
      }

      span[data-side="3"] {
        transform: translate(-50%, -100%);
      }
    }

    &__countdown-value {
      @include font("f-display-1");
      position: relative;
      font-weight: 700;
      z-index: 1;
      text-align: center;
      color: var(--clr-text-title);
    }

    &__skip {
      opacity: 0;
      pointer-events: none;
      min-width: fluid(116, 144);
      gap: fluid(8, 12);
      color: var(--clr-text-title);
      transition:
        opacity 0.28s ease,
        transform 0.28s ease,
        box-shadow 0.28s ease;

      .no-loop-filter-rect {
        margin-right: fluid(2, 4);
      }
    }

    &__skip-wrap {
      position: fixed;
      top: calc(var(--header-height) + var(--gutter-xl));
      left: 50%;
      transform: translateX(-50%);
      z-index: 6;
      display: flex;
      justify-content: center;
      pointer-events: none;
    }

    &__content {
      width: 100%;
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      justify-content: center;
      gap: var(--gutter-md);
      &.content-1 {
        width: 50%;

        @include mq(lg) {
          width: 50%;
        }
      }
      &.content-2 {
        width: 42%;
        left: inherit;
        right: 0;

        @include mq(lg) {
          width: 50%;
        }
      }

      @include mq(md) {
        position: relative;
        inset: auto;
        width: 100%;
        flex: 0 0 100%;
        justify-content: flex-start;

        &.content-1,
        &.content-2 {
          width: 100%;
        }

        &.content-2 {
          left: auto;
          right: auto;
          margin-top: var(--gutter-xl);
        }
      }

      @include mq(sm) {
        gap: var(--gutter-sm);

        &.content-2 {
          margin-top: var(--gutter-lg);
        }
      }
    }
  }
  &-hero {
