      width: 100%;
      height: 100%;
      margin-top: var(--header-height);
    }

    &__body {
      width: 100%;
    }

    &__block {
      margin-bottom: var(--gutter-3xl);
      height: 100vh;
      &:first-child {
        width: 42%;
        margin-left: auto;
