      top: var(--header-height);
      min-height: calc(100vh - var(--header-height));
      display: flex;
      align-items: center;
      justify-content: center;

      @include mq(md) {
        position: relative;
        top: auto;
        min-height: auto;
        padding: var(--gutter-3xl) 0;
      }
    }

    &__desc {
      margin-top: var(--gutter-sm);
      .line {
        text-align: center;
      }
      p + p {
        margin-top: var(--gutter-xs);
      }
    }

    &__action {
      @include flex-center();
      margin-top: var(--gutter-xl);
    }
  }

  &-feature-card-list {
    display: flex;
    flex-direction: column;
    gap: var(--gutter-lg);
  }

  &-feature-card {
    display: flex;
    gap: var(--gutter-md);
    padding: var(--gutter-md);
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(255, 255, 255, 0.02);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);

    &__figure {
      position: relative;
      width: fluid(148, 288);
      aspect-ratio: 1 / 1;
      overflow: hidden;
      flex-shrink: 0;
    }

    &__canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    &__txt {
      display: flex;
      flex-direction: column;
      margin-top: var(--gutter-md);
    }

    &__title,
    &__desc,
    &__tags {
      width: 100%;
    }
    &__desc {
      margin-top: var(--gutter-sm);
    }

    &__tags {
      margin-top: var(--gutter-xs);
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-2xs);

      span {
        @include font("f-body-3");
        padding: var(--gutter-3xs) var(--gutter-xs);
        border: 1px solid rgba(255, 255, 255, 0.14);
        color: var(--clr-text-desc);
      }
    }
  }

  &-why {
    width: 100%;

    &__wrap {
      min-height: var(--scene-shell-span);
      position: relative;

      > .no-container-2xl {
        min-height: inherit;
      }
    }

    &__inner {
      width: 100%;
      display: flex;
      align-items: center;
    }

    // ── 스킬 리스트 ────────────────────────────────
    &__skill-list {
      width: 100%;
      text-align: center;
    }

    &__skill-item {
      position: relative;
      padding: fluid(10, 24) 0;
      cursor: default;
      transition: opacity var(--transition-base);
    }

    &__skill-list:has(&__skill-item:hover) &__skill-item:not(:hover) {
      opacity: 0.2;
    }

    &__skill-label {
      display: block;
      line-height: 1;
    }

    &__skill-desc {
      position: absolute;
      right: 0;
      top: 50%;
      transform: translateY(-50%);
      opacity: 0;
      transition: opacity 0.24s ease;
      white-space: nowrap;
    }

    @include mq(lg) {
      &__skill-desc {
        display: none;
      }

      &__skill-item:hover &__skill-desc {
        opacity: 0;
      }
    }

    &__skill-item:hover &__skill-desc {
      opacity: 0.64;
    }

    // ── 비디오 프리뷰 ──────────────────────────────
    &__preview {
      position: fixed;
      top: 0;
      left: fluid(24, 56);
      transform: translateY(-50%);
      width: fluid(320, 560);
      aspect-ratio: 16 / 9;
      overflow: hidden;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      clip-path: inset(50% 0 50% 0);
      transition:
        opacity 0.4s cubic-bezier(0.76, 0, 0.24, 1),
        visibility 0.4s cubic-bezier(0.76, 0, 0.24, 1),
        clip-path 0.48s cubic-bezier(0.76, 0, 0.24, 1),
        top 0.44s cubic-bezier(0.76, 0, 0.24, 1);
      z-index: 100;

      &.is-visible {
        opacity: 1;
        visibility: visible;
        clip-path: inset(0% 0 0% 0);
      }

      &.is-visible.is-switching {
        clip-path: inset(50% 0 50% 0);
      }

      &.is-closing {
        opacity: 0;
        clip-path: inset(50% 0 50% 0);
      }
    }

    &__preview-video {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    @include mq(md) {
      &__inner {
        position: relative;
        top: auto;
        height: auto;
        min-height: 100vh;
      }

      &__preview {
        display: none;
      }
    }
  }
  &-services {
