    &__list {
      width: 100%;

      @include mq(md) {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: var(--gutter-xl) var(--gutter-lg);
      }

      @include mq(sm) {
        grid-template-columns: 1fr;
