  // 클라이언트 섹션: 리스트는 12칸 중 오른쪽 5칸, ul은 2열 그리드. 스크롤에 따라 list가 100%→-100% 이동
  &-clients {
    $root: &;
    > div {
      display: grid;
      grid-template-columns: 4fr 8fr;
      gap: var(--gutter-2xl);
      align-items: flex-start;
    }

    &__head-wrap {
      position: sticky;
      top: calc(var(--header-height) + var(--gutter-lg));
      align-self: start;
    }

    &__head {
      position: relative;
      height: fit-content;
      p {
        @include font("f-body-1");
        margin-top: var(--gutter-md);
      }
    }

    &__list {
      position: relative;
    }

    &__items {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: var(--gutter-md);
    }

    &__item {
      background: rgba(255, 255, 255, 0.04);
      padding: var(--gutter-md);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);

      &.is-block-reveal {
        transition-delay: 0s;
      }

      a {
        display: block;
      }
      img {
        display: block;
      }
    }

    @for $i from 1 through 22 {
      &__item:nth-child(#{$i}).is-block-reveal {
        transition-delay: #{($i - 1) * 45}ms;
      }
    }

    @include mq(md) {
      > div {
        grid-template-columns: 1fr;
      }

      &__head-wrap {
        position: relative;
        top: auto;
      }

      &__items {
        gap: var(--gutter-sm);
      }
    }
