      justify-content: space-between;
      align-items: flex-start;
      padding-bottom: fluid(32, 48);
      border-bottom: 1px solid var(--clr-border-default);
      gap: var(--gutter-lg);
      @include mq(md) {
        flex-direction: column;
        align-items: flex-start;
      }

      @include mq(sm) {
        gap: var(--gutter-md);
      }
    }

    &__logo {
      a {
        display: block;
        text-decoration: none;
      }
      img {
