        height: auto;
        object-fit: contain;
      }
    }

    &__nav {
      flex-shrink: 0;
    }

    &__menu {
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-xl) var(--gutter-2xl);
      @include mq(md) {
        flex-direction: column;
        gap: var(--gutter-md);
      }

      @include mq(sm) {
        width: 100%;
      }
    }

    &__menu-item {
      &--has-sub {
        display: flex;
        flex-direction: column;
        gap: var(--gutter-xs);
      }
    }

    &__menu-link {
      @include font("f-heading-4");
      font-weight: 600;
      color: var(--clr-text-title);
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-trigger-link);
      }
    }

    &__sub {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xs);
    }

    &__sub-link {
      @include font("f-body-2");
      font-weight: 400;
      color: var(--clr-text-body);
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-text-title);
      }
    }

    &__bottom {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      gap: var(--gutter-xl);
      padding-top: fluid(32, 48);
      @include mq(md) {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--gutter-lg);
      }

      @include mq(sm) {
        gap: var(--gutter-md);
      }
    }

    &__info {
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-lg) var(--gutter-2xl);
      @include mq(md) {
        flex-direction: column;
        gap: var(--gutter-md);
      }

      @include mq(sm) {
        width: 100%;
      }
    }

    &__info-block {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xs);
    }

    &__info-title {
      @include font("f-body-2");
      font-weight: 600;
      color: var(--clr-text-desc);
      letter-spacing: 0.02em;
    }

    &__info-text {
      @include font("f-body-2");
      font-weight: 400;
      color: var(--clr-text-body);
    }

    &__info-link {
      color: inherit;
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-trigger-link);
      }
    }

    &__contact {
      flex-shrink: 0;
    }

    &__contact-link {
      @include font("f-heading-4");
      font-weight: 600;
      color: var(--clr-text-title);
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-trigger-link);
      }
    }
  }
}

