import {
  BACKGROUND_APP_DOM as APP_MANAGER_DOM,
  CONTACT_HEAD_TRANSITION,
  WORKS_DETAIL_HEAD_TRANSITION,
} from "../../../config/transition.config.js";
import type {
  PageSceneRuntimePolicy,
  SceneBackgroundPolicy,
  SceneProgressOptionsMap,
  SceneSelectorMap,
} from "../../../types/runtime.types.js";
import type {
  BackgroundTransitionRule,
  BackgroundVariantKey,
  SceneProgressTransitionWindow,
} from "../../../types/object-runtime.types.js";

const MAIN_THEATRE_QUERY_KEY = "theatre";
const MAIN_THEATRE_QUERY_ENABLED = "1";
const WHO_TEXT_SELECTOR = ".no-main-who .mask-target";
let _whoTextItems: HTMLElement[] | null = null;
function getWhoTextItems(): HTMLElement[] {
  if (_whoTextItems !== null) return _whoTextItems;
  _whoTextItems = Array.from(document.querySelectorAll<HTMLElement>(WHO_TEXT_SELECTOR));
  return _whoTextItems;
}
const WHO_REVEAL_START = 0.12;
const WHO_REVEAL_END = 0.92;
const WHO_REVEAL_STAGGER_SECONDS = 0.12;
const CLIENT_ITEM_SELECTOR = ".no-main-clients__item";
let _clientItems: HTMLElement[] | null = null;
function getClientItems(): HTMLElement[] {
  if (_clientItems !== null) return _clientItems;
  _clientItems = Array.from(document.querySelectorAll<HTMLElement>(CLIENT_ITEM_SELECTOR));
  return _clientItems;
}
const CLIENT_REVEAL_START = 0.08;
const CLIENT_REVEAL_END = 0.96;
const CLIENT_REVEAL_STAGGER_SECONDS = 0.045;
const CONTACT_SECTION_SELECTOR = ".no-main-contact";
const CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
const CONTACT_ACTIONS_SELECTOR = ".no-main-contact__actions";
const CONTACT_ACTION_ITEM_SELECTOR =
  ".no-main-contact__actions > .no-corner-btn-wrap";
let _contactSectionEl: HTMLElement | null = null;
let _contactHeadEl: HTMLElement | null = null;
let _contactActionsEl: HTMLElement | null = null;
let _contactTextItems: HTMLElement[] | null = null;
let _contactActionItems: HTMLElement[] | null = null;
function getContactSection(): HTMLElement | null {
  if (_contactSectionEl?.isConnected) return _contactSectionEl;
  _contactSectionEl = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
  return _contactSectionEl;
}
function getContactHead(): HTMLElement | null {
  if (_contactHeadEl?.isConnected) return _contactHeadEl;
  _contactHeadEl = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
  return _contactHeadEl;
}
function getContactActions(): HTMLElement | null {
  if (_contactActionsEl?.isConnected) return _contactActionsEl;
  _contactActionsEl = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
  return _contactActionsEl;
}
function getContactTextItems(): HTMLElement[] {
  if (_contactTextItems !== null) return _contactTextItems;
  const head = getContactHead();
  _contactTextItems = head ? Array.from(head.querySelectorAll<HTMLElement>(".mask-target")) : [];
  return _contactTextItems;
}
function getContactActionItems(): HTMLElement[] {
  if (_contactActionItems !== null) return _contactActionItems;
  _contactActionItems = Array.from(document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR));
  return _contactActionItems;
}
const WORKS_DETAIL_HEAD_SELECTOR = APP_MANAGER_DOM.portfolioHeadSelector;
let _worksDetailHeadEl: HTMLElement | null = null;
let _worksDetailHeadTextItems: HTMLElement[] | null = null;
function getWorksDetailHead(): HTMLElement | null {
  if (_worksDetailHeadEl?.isConnected) return _worksDetailHeadEl;
