1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import type { SceneObjectContext } from "../../types/engine.types.js";
4	import type {
5	  GravityBallsObjectOptions,
6	  GravityBallsTweenProps,
7	  SmokeFloorRuntime,
8	} from "../../types/object.types.js";
9	
10	interface SphereInfo {
11	  ID: number;
12	  startX: number;
13	  startY: number;
14	  startZ: number;
15	  spawnX: number;
16	  spawnY: number;
17	  vx: number;
18	  vy: number;
19	  vz: number;
20	  gravity: number;
21	  rotDir: number;
22	  shrinkRate: number;
23	  initScale: number;
24	  bounced: boolean;
25	  vxMult: number;
26	  vzMult: number;
27	  vyMult: number;
28	  age: number;
29	  sphere: THREE.Sprite;
30	  material: THREE.SpriteMaterial;
31	}
32	
33	type ResolvedOpts = {
34	  attachTo: string;
35	  spawnOffset: { x?: number; y?: number; z?: number };
36	  colors: string[];
37	  dotsPerInterval: number;
38	  physicsScale: number;
39	  proximityRange: number;
40	  maxGravityBoost: number;
41	  vxMult: number;
42	  vzMult: number;
43	  vyMult: number;
44	  particleScaleMin: number;
45	  particleScaleMax: number;
46	};
47	
48	const FADE_START_SCALE = 0.65;
49	const SMOKE_Z_DRIFT = 0.002;
50	const SMOKE_SPREAD = 1.005;
51	const DEFAULT_PARTICLE_SCALE_MIN = 1.2;
52	const DEFAULT_PARTICLE_SCALE_MAX = 3.0;
53	const LIFETIME_TICKS = 90;
54	const FADE_START_TICK = Math.floor(LIFETIME_TICKS * 0.55);
55	const SMOKE_FLOOR_RUNTIME_KEY = "smokeFloor.runtime";
56	
57	const DEFAULT_TEXTURE_URLS = [
58	  "/resource/images/texture/smoke/smoke_01.png",
59	  "/resource/images/texture/rocket/smoke.png",
60	];
61	
62	const DEFAULTS = {
63	  attachTo: "rocket",
64	  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
65	  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
66	  dotsPerInterval: 3,
67	  physicsScale: 0.006,
68	  proximityRange: 4.0,
69	  maxGravityBoost: 3.0,
70	  vxMult: 2.5,
71	  vzMult: 1.5,
72	  vyMult: -0.5,
73	  gravityBase: 10,
74	  floorLevel: -2.5,
75	  floorDimensions: 25,
76	};
77	
78	export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
79	  private readonly _balls = new Map<number, SphereInfo>();
80	  private _idx = 0;
81	  private _accumMs = 0;
82	  private readonly _spawnPt = new THREE.Vector3();
83	  private _opts: GravityBallsObjectOptions = {};
84	  private _baseMats: THREE.SpriteMaterial[] = [];
85	
86	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
87	    if (props) this._opts = { ...this._opts, ...props };
88	    return this;
89	  }
90	
91	  protected override getOptions(): Record<string, unknown> {
92	    return this._opts as Record<string, unknown>;
93	  }
94	
95	  override async runObject(): Promise<void> {
96	    const ctx = this._context;
97	    if (!ctx) return;
98	
99	    const urls: string[] =
100	      this._opts.textureUrls?.length ? this._opts.textureUrls
101	      : this._opts.textureUrl ? [this._opts.textureUrl]
102	      : DEFAULT_TEXTURE_URLS;
103	
104	    const textures = await Promise.all(
105	      urls.map(async (url): Promise<THREE.Texture | null> => {
106	        if (!url || !ctx.loadTexture) return null;
107	        try { return await ctx.loadTexture(this.resolveAssetPath(url)); }
108	        catch { return null; }
109	      }),
110	    );
111	
112	    this._baseMats = textures.length > 0
113	      ? textures.map(tex => new THREE.SpriteMaterial({
114	          map: tex ?? null,
115	          transparent: true,
116	          depthWrite: false,
117	          opacity: 0.8,
118	        }))
119	      : [new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0.8 })];
120	
121	    this._applyOptionVisibility();
122	  }
123	
124	  override runUpdate(delta: number): void {
125	    const ctx = this._context;
126	    if (!ctx || this._disposed || !this.getVisibleState()) return;
127	
128	    this._accumMs += delta * 1000;
129	    if (this._accumMs >= 15) {
130	      this._accumMs -= 15;
131	      this._tick(ctx);
132	    }
133	  }
134	
